package com.sunmo.stockplatform.analytics;
import com.sunmo.stockplatform.analytics.domain.*;import com.sunmo.stockplatform.scanner.domain.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import static org.assertj.core.api.Assertions.*;
class DetectionPerformanceTest {
 private final Instant detected=Instant.parse("2026-08-19T00:00:00Z");
 @Test void fillsMilestonesAndCalculatesReturns(){DetectionPerformance p=new DetectionPerformance(detection());p.observe(bd("110"),detected.plusSeconds(300));p.observe(bd("90"),detected.plusSeconds(600));p.observe(bd("120"),detected.plusSeconds(1800));p.observe(bd("80"),detected.plusSeconds(3600));p.finalizeClose(bd("105"),detected.plusSeconds(23000));assertThat(p.getStatus()).isEqualTo(PerformanceStatus.COMPLETED);assertThat(p.getReturn5m()).isEqualByComparingTo("10.000000");assertThat(p.getReturn10m()).isEqualByComparingTo("-10.000000");assertThat(p.getReturnClose()).isEqualByComparingTo("5.000000");assertThat(p.getMaxReturn()).isEqualByComparingTo("20.000000");assertThat(p.getMaxDrawdown()).isEqualByComparingTo("-20.000000");}
 @Test void marksMissingMilestonesInsteadOfWritingZero(){DetectionPerformance p=new DetectionPerformance(detection());p.observe(bd("102"),detected.plusSeconds(300));p.finalizeClose(bd("103"),detected.plusSeconds(1000));assertThat(p.getStatus()).isEqualTo(PerformanceStatus.DATA_MISSING);assertThat(p.getReturn10m()).isNull();assertThat(p.getReturn30m()).isNull();}
 private ScannerDetection detection(){ScannerSetting setting=new ScannerSetting(1L,"Momentum",ScannerType.MOMENTUM,bd("2"),bd("2"),bd("0"),bd("0"),bd("0"),false,300);return new ScannerDetection(UUID.randomUUID(),null,setting,detected,bd("100"),bd("2"),bd("2"),10,bd("1000"),bd("10000"),bd("4"),"{}","test");}private BigDecimal bd(String value){return new BigDecimal(value);}
}
